const fromWebhook = $input.first().json.body?.chatId;
const chatId = fromWebhook || '6537042237';
return [{ json: { chatId } }];

const raw = $input.first().json;

const xml = raw.data || raw.body || raw.text || raw.response || (typeof raw === 'string' ? raw : '');

if (!xml || xml.length < 100) {
  throw new Error('News RSS returned empty or invalid data. Raw response: ' + JSON.stringify(raw).substring(0, 300));
}

// Extract <item> blocks first, then pull <title> from each — avoids matching the feed-level <title>
const items = [];
const itemRegex = /<item[\s\S]*?<\/item>/g;
let itemMatch;
while ((itemMatch = itemRegex.exec(xml)) !== null) items.push(itemMatch[0]);

if (items.length === 0) {
  throw new Error('No <item> elements found in RSS. First 500 chars: ' + xml.substring(0, 500));
}

const titleRegex = /<title>(?:<!\[CDATA\[)?(.*?)(?:\]\]>)?<\/title>/;
const sourceRegex = /<source[^>]*>(.*?)<\/source>/;

const newsList = items.slice(0, 15).map((item, i) => {
  const titleMatch = item.match(titleRegex);
  const sourceMatch = item.match(sourceRegex);
  const title = titleMatch ? titleMatch[1].trim() : '';
  const source = sourceMatch ? sourceMatch[1].trim() : '';
  return { rank: i + 1, title, source };
}).filter(n => n.title.length > 0);

if (newsList.length === 0) {
  throw new Error('Items found but no titles extracted. First item: ' + items[0].substring(0, 300));
}

const chatId = $('Get ChatId').first().json.chatId;

return [{ json: {
  news: newsList,
  trendsText: newsList.map(n => `${n.rank}. ${n.title}${n.source ? ' — ' + n.source : ''}`).join('\n'),
  fetchedAt: new Date().toISOString(),
  chatId
} }];

const data = $input.first().json;

if (!data.trendsText || data.trendsText.trim() === '') {
  throw new Error('trendsText is empty — the Parse Trends RSS node returned no data. Check that node first.');
}

const visualStyle = 'VISUAL STYLE (apply to every poster, never change this): Square 1:1 format. High-contrast black-and-white photographic figure, partially hidden through circular masks and geometric overlays. Color palette: grayscale + bold green (#22C55E) on geometric elements only (circles, arcs, overlays). Background: light off-white or soft gray with subtle grain/noise texture. The ONLY readable text is UDARSY in clean modern sans-serif, top-right corner, 5% padding — no other text anywhere. UI details: thin dividers, minimal markers, abstract labels without text. Composition: asymmetry, overlapping masks, rotated/layered geometric structures, depth. Vary scale, masking, and subject placement each time. Lighting: high contrast editorial style.';

const body = {
  model: 'gpt-4o',
  max_tokens: 1200,
  temperature: 0.9,
  messages: [
    {
      role: 'system',
      content: 'You are a creative poster designer. You create visually striking editorial posters about any topic — sports, politics, entertainment, science, anything. Output ONLY valid JSON, no markdown, no code blocks.'
    },
    {
      role: 'user',
      content: `Today's top news headlines in Morocco:

${data.trendsText}

Step 1 — Pick the single most relevant LOCAL Moroccan topic from the list.
PRIORITY ORDER (pick the highest available):
  1. Moroccan politics, government, economy, laws, official decisions
  2. Moroccan society, culture, local events, Moroccan celebrities
  3. Moroccan sports teams specifically (Raja, Wydad, ASFAR, Atlas Lions national team)
  4. Moroccan education, BAC, Brevet, ministry of education news
  5. Only if nothing local exists: any other topic from the list
AVOID: matches between two foreign teams (e.g. Man City vs Liverpool), foreign celebrities with no Morocco connection, generic world news.

Step 2 — Think about what visuals, symbols, actions, or objects represent THAT specific Moroccan topic.
Step 3 — Write a DALL-E 3 image prompt where every visual element is directly about the chosen topic.

${visualStyle}

Rules for the image_prompt field:
- The subject MUST visually represent the chosen Moroccan topic specifically
- Do NOT default to students or school imagery unless the topic is about education
- Describe the subject, pose, and symbolic elements that make the topic immediately recognizable
- Apply the visual style above

Respond with ONLY this JSON:
{"chosen_trend":"exact headline from the list","why_chosen":"one sentence explaining why this is the most locally Moroccan topic","angle":"informative|inspirational|commentary|satirical|cultural","subject_description":"one sentence: what the human figure is doing and what makes it represent the topic","image_prompt":"[Full DALL-E 3 prompt. Start with: A black-and-white high-contrast editorial photograph of [specific figure/action directly representing the chosen Moroccan topic], partially hidden by circular geometric masks, bold green (#22C55E) arc and circle overlays, off-white grainy background, the word UDARSY in clean modern sans-serif top-right corner only, no other text, asymmetric editorial composition, thin UI dividers, layered geometric depth, square 1:1 format]","caption":"social media caption in Moroccan Darija mixed with French naturally, relevant hashtags including #دارسي #المغرب","language":"ar"}`
    }
  ]
};
return [{ json: { body, chatId: data.chatId } }];

const raw = $input.first().json;
const chatId = $('Build GPT Prompt').first().json.chatId;
const text = raw.choices?.[0]?.message?.content || '';
let parsed;
try {
  parsed = JSON.parse(text.replace(/^```json\s*/i, '').replace(/```\s*$/i, '').trim());
} catch(e) {
  throw new Error('Could not parse GPT response: ' + text.substring(0, 300));
}
return [{ json: { ...parsed, chatId } }];

const dalleResp = $input.first().json;
const concept = $('Parse Poster Concept').first().json;
const imageUrl = dalleResp.data?.[0]?.url || '';
if (!imageUrl) throw new Error('DALL-E returned no image URL: ' + JSON.stringify(dalleResp).substring(0, 300));
return [{ json: { ...concept, imageUrl } }];

const concept = $('Extract Image URL').first().json;
const binary = $('Download Poster Image').first().binary;

// Build plain-text caption — no Markdown to avoid parse errors
let caption = '🎨 NEW POSTER READY FOR REVIEW\n\n';
caption += '📊 Trend: ' + (concept.chosen_trend || '') + '\n';
caption += '🎯 Angle: ' + (concept.angle || '') + '\n';
caption += '💬 Caption: ' + (concept.caption || '') + '\n\n';
caption += 'Tap a button below to respond:';

return [{ json: { chatId: concept.chatId, caption }, binary }];
